+const TOOL_NAME = 'events_list';
+const DEFAULT_PAGE_SIZE = 2;
+const MIN_PAGE_SIZE = 1;
+const MAX_PAGE_SIZE = 3;
+
+function encodeCursor(offset) {
+  return Buffer.from(JSON.stringify({ o: offset }), 'utf8').toString('base64url');
+}
+
+function decodeCursor(cursor) {
+  let parsed;
+  try {
+    parsed = JSON.parse(Buffer.from(cursor, 'base64url').toString('utf8'));
+  } catch {
+    throw new Error('Unknown cursor');
+  }
+  if (
+    !parsed || typeof parsed !== 'object' ||
+    typeof parsed.o !== 'number' || !Number.isInteger(parsed.o) ||
+    parsed.o < 0 || parsed.o > events.length
+  ) {
+    throw new Error('Unknown cursor');
+  }
+  return parsed.o;
+}
+
+export async function listTools() {
+  return [
+    {
+      name: TOOL_NAME,
+      description: 'List events in source order with optional cursor pagination.',
+      inputSchema: {
+        type: 'object',
+        properties: {
+          cursor: {
+            type: 'string',
+            description: 'Opaque pagination cursor returned by a previous events_list call.'
+          },
+          page_size: {
+            type: 'integer',
+            description: 'Number of events to return per page (1 to 3, default 2).'
+          }
+        },
+        required: [],
+        additionalProperties: false
+      }
+    }
+  ];
+}
+
+export async function callTool(name, args = {}) {
+  if (name !== TOOL_NAME) {
+    throw new Error(`Unknown tool: ${name}`);
+  }
+
+  for (const key of Object.keys(args)) {
+    if (key !== 'cursor' && key !== 'page_size') {
+      throw new Error(`Unknown field: ${key}`);
+    }
+  }
+
+  const { cursor, page_size } = args;
+
+  if (cursor !== undefined && typeof cursor !== 'string') {
+    throw new Error('cursor must be a string');
+  }
+
+  let pageSize = page_size;
+  if (pageSize === undefined) {
+    pageSize = DEFAULT_PAGE_SIZE;
+  } else if (
+    typeof pageSize !== 'number' || !Number.isInteger(pageSize) ||
+    pageSize < MIN_PAGE_SIZE || pageSize > MAX_PAGE_SIZE
+  ) {
+    throw new Error('page_size must be an integer from 1 to 3');
+  }
+
+  let offset = 0;
+  if (cursor !== undefined) {
+    offset = decodeCursor(cursor);
+  }
+
+  const slice = events.slice(offset, offset + pageSize);
+  const result = { events: slice };
+  if (offset + pageSize < events.length) {
+    result.next_cursor = encodeCursor(offset + pageSize);
+  }
+
+  return {
+    content: [
+      { type: 'text', text: JSON.stringify(result) }
+    ]
+  };
